-- Populate public display `instructions` for the seeded payment methods so the
-- checkout surface is fully driven by the database instead of hardcoded
-- frontend constants. `config` stays empty until an administrator configures it.

UPDATE "payment_methods" SET "instructions" = '{"tagline":"Pay instantly using the Telebirr mobile money app.","tips":["Enter the transaction number you receive after payment.","Use the exact amount shown for your course."],"securityNotice":"Never share your Telebirr password or PIN with anyone.","transactionIdLabel":"Telebirr transaction ID","transactionIdPlaceholder":"e.g. 1234567890"}', "updated_at" = now() WHERE "code" = 'TELEBIRR';--> statement-breakpoint
UPDATE "payment_methods" SET "instructions" = '{"tagline":"Transfer directly from your Commercial Bank of Ethiopia account.","tips":["After the transfer, copy the reference or receipt number.","Enter the exact reference number so we can match your payment."],"securityNotice":"Only use your official CBE account to send the transfer.","transactionIdLabel":"CBE Birr reference / receipt number","transactionIdPlaceholder":"e.g. CBE-0987654321"}', "updated_at" = now() WHERE "code" = 'CBE_BIRR';--> statement-breakpoint
UPDATE "payment_methods" SET "instructions" = '{"tagline":"Card, mobile money, and bank payments through one secure checkout.","tips":["Follow the Chapa checkout link to complete payment.","Enter the checkout transaction reference here."],"securityNotice":"Chapa handles all card details - we never see them.","transactionIdLabel":"Chapa transaction reference","transactionIdPlaceholder":"e.g. 5f2a8c1d-0001"}', "updated_at" = now() WHERE "code" = 'CHAPA';--> statement-breakpoint
UPDATE "payment_methods" SET "instructions" = '{"tagline":"Transfer from any bank via mobile banking, internet banking, or a branch visit.","tips":["Use the account details shown on the screen.","Upload the receipt or transfer confirmation you receive.","Write your name and course as the payment reference if possible."],"securityNotice":"Only transfer to the official academy account details shown here.","transactionIdLabel":"Bank transfer reference / receipt number","transactionIdPlaceholder":"e.g. TRF-11223344"}', "updated_at" = now() WHERE "code" = 'BANK_TRANSFER';
